// Registers both RPC contracts. Owned by P0. Packages do not edit this file:
// each one fills in its handler map in its own register-*.ts file.
import { readContract, receiveContract, rpcContract } from "../shared/contract.js";
import type { ServerContext } from "./context.js";
import { readCalls } from "./memory.js";
import { coreRpcHandlers } from "./register-core.js";
import { phoneRpcHandlers, receiveRpcHandlers } from "./register-phone.js";

export function registerRpc(ctx: ServerContext): void {
  ctx.bb.rpc.register(rpcContract, {
    ...coreRpcHandlers(ctx),
    ...phoneRpcHandlers(ctx),
  });
  // The Webhooks plugin finds this method by discovery and forwards verified
  // OpenAI phone events to it.
  ctx.bb.rpc.register(receiveContract, receiveRpcHandlers(ctx), {
    experimental_discoverable: true,
    experimental_description: "Takes OpenAI live.transport.incoming events and answers the phone call.",
  });
  // An optional read-only integration: Journal may read call summaries when the
  // user turns that on in Journal. Nothing else is discoverable.
  ctx.bb.rpc.register(
    readContract,
    { "read.calls": (input) => readCalls(ctx, input) },
    {
      experimental_discoverable: true,
      experimental_description:
        "Lists Dispatch voice calls that overlap a window of at most 62 days, with a title, summary, and thread ids for each. Read-only.",
    },
  );
}
